function icon(name,cls=''){return `<svg class="ui-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`}
const navSections=[['overview','home','Journey'],['items','bag','Satchel'],['equipment','party','Travelers'],['abilities','spark','Abilities'],['journal','book','Journal'],['map','map','Region map'],['settings','gear','Settings'],['controls','help','Guide']];
function partyRail(){return `<aside class="party-rail" aria-label="Party status"><span class="ui-kicker">YOUR TRAVELERS</span>${heroes.map((h,i)=>`<div class="rail-traveler"><div class="rail-sprite" style="background-image:var(--portrait${i})"></div><div><h3>${h.name}</h3><small>${h.job}<br>Level ${h.level}</small></div>${statBar(h)}${statBar(h,'sp')}</div>`).join('')}<div class="rail-location">${icon('map')}<span class="ui-kicker">CURRENT LOCATION</span><b>${currentDef.name}</b>${currentDef.subtitle}</div><div class="rail-time">${icon('clock')}${String(Math.floor(state.playtime/3600)).padStart(2,'0')}:${String(Math.floor(state.playtime/60)%60).padStart(2,'0')}:${String(Math.floor(state.playtime)%60).padStart(2,'0')}</div></aside>`}
function regionAtlas(){const points=[[18,68],[35,59],[52,43],[71,48],[83,25]],visited=state.sceneVisited||['village'];const selected=ui.mapSelected||state.area,d=sceneDefs[selected];return `<div class="region-atlas"><div class="atlas-ink-title"><span>THE RIVERLANDS</span><small>Rivers, roots & forgotten light</small></div>${sceneOrder.map((id,i)=>`<button class="atlas-marker ${id===state.area?'current':''} ${visited.includes(id)?'discovered':''}" style="left:${points[i][0]}%;top:${points[i][1]}%" data-map-select="${id}" aria-label="Inspect ${sceneDefs[id].name}">${icon(['home','clock','map','leaf','spark'][i])}<span>${sceneDefs[id].name}</span></button>`).join('')}<div class="atlas-compass">N<div>✧</div>S</div><div class="atlas-caption"><i></i> Your location <i></i> Discovered destination</div></div><div class="atlas-selection"><div>${icon(selected==='village'?'home':'map')}<span><b>${d.name}</b><small>${d.subtitle}</small></span></div>${button(selected===state.area?'You are here':visited.includes(selected)?'Revisit destination':'Undiscovered','atlas-travel:'+selected,'secondary',selected===state.area||!visited.includes(selected))}</div>`}
const itemMeta={herb:{category:'restoratives',icon:'leaf',color:'sage',effect:'120 HP',lore:'Sweet riverland grapes. An everyday kindness, carefully wrapped for the road.'},ether:{category:'restoratives',icon:'spark',color:'blue',effect:'30 MP',lore:'A cool-blue plum, harvested where the river catches the evening stars.'},revive:{category:'restoratives',icon:'heart',color:'rose',effect:'Revive · 50% HP',lore:'A silver-green olive whose oil shelters a tiny spark of life.'},sword:{category:'equipment',icon:'sword',color:'gold',effect:'+14 attack · Aren',lore:'A balanced blade from Halden’s forge, with a warm line of dawnsteel along its edge.'},robe:{category:'equipment',icon:'shield',color:'blue',effect:'+7 defense · Mira',lore:'Fine silver-threaded cloth that gathers a little of the night sky.'},ember:{category:'key',icon:'flame',color:'gold',effect:'Quest item',lore:'The old ward’s living heart. Its light belongs to the people of Willowmere.'}};
const abilityData=[{id:'crosscut',hero:0,name:'Crosscut',cost:8,icon:'sword',target:'One foe · 2 hits',text:'Two measured sword strikes. Each hit can remove a shield when sword is a weakness.'},{id:'fire',hero:0,name:'Sunfire',cost:12,icon:'flame',target:'All foes · fire',text:'A rising circle of flame. Exploit a fire weakness to strip shields from the enemy line.'},{id:'ice',hero:1,name:'Frostfall',cost:10,icon:'ice',target:'All foes · ice',text:'Crystalline ice erupts beneath the enemy. Each vulnerable foe loses a shield.'},{id:'lightning',hero:1,name:'Starfall',cost:16,icon:'bolt',target:'All foes · lightning',text:'A powerful lightning strike. Costs more spirit, but deals the strongest elemental damage.'},{id:'heal',hero:1,name:'Mending light',cost:9,icon:'heart',target:'One traveler · 100 HP',text:'A gentle restorative light. Can be used between battles while Mira has enough MP.'}];
function statBar(h,type='hp'){const value=h[type],max=h[type==='hp'?'maxHp':'maxSp'];return `<div class="stat-meter ${type}"><span>${type==='hp'?'HP':'MP'}</span><div><i style="width:${value/max*100}%"></i></div><b>${value}<small> / ${max}</small></b></div>`}
function face(i,large=false){return `<div class="ui-face ${large?'large':''}" style="--face-image:var(--face${i})"><div></div></div>`}
function itemArt(k){return `<div class="item-art ${itemMeta[k]?.color||'gold'}">${icon(itemMeta[k]?.icon||'spark')}</div>`}
function button(text,action,cls='primary',disabled=false){return `<button class="ui-button ${cls}" data-ui="${action}" ${disabled?'disabled':''}>${text}</button>`}
function subtitle(text){return `<p class="ui-subtitle">${text}</p>`}
function empty(text){return `<div class="ui-empty">${icon('bag')}<h3>Nothing here yet</h3><p>${text}</p></div>`}
function chapterSteps(){return [['An evening in Willowmere','Speak to Elder Rowan beside the fountain.'],['Along the river roads','Cross Riverbank Walk and Crown Highroad.'],['The old ward','Defeat the Hollow Warden at the shrine.'],['Carry the ember home','Collect the ember and return to Rowan.'],['A light remains','The ward is restored. Keep exploring.']]}
function renderShell(title,kicker,content,detail='',section=modalTab){
 const focused=document.activeElement?.dataset?.focusKey;$('#modal').innerHTML=`<section class="ui-shell ${detail?'has-detail':''}" role="dialog" aria-modal="true" aria-label="${title}"><header class="ui-header"><div class="ui-title-lockup"><span class="ui-kicker">${kicker}</span><h2>${title}</h2></div><div class="ui-wallet">${icon('coin')}<strong>${state.gold.toLocaleString()}</strong><span>leaves</span></div><button class="ui-close" id="close-menu" aria-label="Close menu">${icon('close')}</button></header><nav class="ui-nav" aria-label="Journal sections">${(titleModal?[['settings','gear','Settings'],['controls','help','Guide']]:navSections).map(([id,i,n])=>`<button data-tab="${id}" class="${section===id?'active':''}" data-focus-key="nav-${id}">${icon(i)}<span>${n}</span>${id===section?'<i></i>':''}</button>`).join('')}<div class="nav-region"><span>THE RIVERLANDS</span><b>${currentDef?.name||'Willowmere'}</b><small>${Math.floor(state.playtime/60)} min traveled</small></div></nav><main class="ui-content">${content}</main>${detail?`<aside class="ui-detail">${detail}</aside>`:''}${partyRail()}<footer class="ui-footer"><span><kbd>↑</kbd><kbd>↓</kbd> Select <kbd>Enter</kbd> Confirm <kbd>Esc</kbd> Back</span><span>EMBER & TIDE <i>·</i> Chapter I</span></footer></section>`;
 $('#close-menu').onclick=()=>closeMenu(true);$$('[data-tab]').forEach(b=>b.onclick=()=>{ui.target=null;ui.query='';modalTab=b.dataset.tab;renderMenu();sfx('click')});bindUIActions();if(focused)$(`[data-focus-key="${focused}"]`)?.focus({preventScroll:true});
}
function overviewPage(){const q=chapterSteps(),stage=state.quest===0?0:state.quest===1?1:state.quest===2?2:state.quest===3?3:4;return `<div class="journey-banner"><span class="ui-kicker">CHAPTER I · A LIGHT REMAINS</span><h3>${$('#quest-title').textContent}</h3><p>${$('#quest-text').textContent}</p><button class="ui-button primary" data-ui="section:journal">Open journal ${icon('arrow')}</button></div><div class="ui-section-heading"><h3>Your travelers</h3><span>2 / 2 in party</span></div><div class="roster-grid">${heroes.map((h,i)=>`<button class="roster-card" data-ui="hero:${i}">${face(i)}<div><span class="ui-kicker">LV ${h.level} · ${h.job}</span><h3>${h.name}</h3>${statBar(h)}${statBar(h,'sp')}</div></button>`).join('')}</div><div class="quick-grid">${[['map','map','Find your way',`${(state.sceneVisited||['village']).length} / 5 places discovered`],['items','bag','Prepare for the road',`${Object.values(state.items).reduce((a,b)=>a+b,0)} supplies carried`],['settings','save','Keep your journey','Save, load and display options']].map(([s,i,t,d])=>`<button data-ui="section:${s}" class="quick-card">${icon(i)}<b>${t}</b><span>${d}</span>${icon('arrow')}</button>`).join('')}</div><div class="ui-note">${icon('map')} Follow signed roads to discover new places. The camera follows you between scenes.</div>`}
function itemDisabled(k,i){const h=heroes[i];if(!state.items[k])return 'None remaining';if(k==='revive')return h.hp>0?'Already standing':'';if(h.hp<=0)return 'Needs an olive of life';if(k==='herb'&&h.hp===h.maxHp)return 'HP already full';if(k==='ether'&&h.sp===h.maxSp)return 'MP already full';return ''}
function inventoryPage(shop=false){const category=ui.category,keys=Object.keys(itemDefs).filter(k=>shop?k!=='ember':state.items[k]>0).filter(k=>category==='all'||itemMeta[k].category===category).filter(k=>itemDefs[k].name.toLowerCase().includes(ui.query.toLowerCase()));if(!keys.includes(ui.selected))ui.selected=keys[0]||null;const k=ui.selected,d=itemDefs[k],m=itemMeta[k];
 const toolbar=`<div class="ui-toolbar"><div class="ui-filters">${[['all','All'],['restoratives','Supplies'],['equipment','Equipment'],...shop?[]:[['key','Key items']]].map(([id,n])=>`<button data-filter="${id}" class="${category===id?'active':''}">${n}</button>`).join('')}</div><label class="ui-search"><span>Search</span><input id="inventory-search" placeholder="Find an item…" value="${ui.query.replace(/"/g,'&quot;')}" autocomplete="off" aria-label="Find an item"></label></div>`;
 const content=subtitle(shop?'Sera’s provisions · Choose an item to inspect it before purchasing.':'Everything your party carries. Select an item to inspect, use or equip it.')+toolbar+`<div class="inventory-list">${keys.length?keys.map(id=>`<button class="inventory-row ${ui.selected===id?'selected':''}" data-select="${id}" data-focus-key="item-${id}">${itemArt(id)}<div><span class="ui-kicker">${itemMeta[id].category}</span><h3>${itemDefs[id].name}</h3><p>${itemMeta[id].effect}</p></div><span class="stack-count">${shop?itemDefs[id].price+' ◈':'× '+state.items[id]}</span></button>`).join(''):empty('Change the filter or search to find your supplies.')}</div>`;
 let detail=k?`<span class="ui-kicker">${m.category} ${state.equipped[k]?'· EQUIPPED':''}</span>${itemArt(k)}<h3>${d.name}</h3><span class="effect-tag">${m.effect}</span><p>${d.desc}</p><p class="item-lore">${m.lore}</p><div class="detail-fact"><span>Carried</span><strong>× ${state.items[k]}</strong></div>`:'';
 if(k&&shop){detail+=`<div class="detail-fact"><span>Price each</span><strong>${d.price} leaves</strong></div><div class="quantity-control"><span>Quantity</span><button data-ui="quantity:-1" aria-label="Buy one fewer">−</button><b>${['sword','robe'].includes(k)?1:ui.shopQty}</b><button data-ui="quantity:1" aria-label="Buy one more" ${['sword','robe'].includes(k)?'disabled':''}>+</button></div>${button('Purchase · '+d.price*(['sword','robe'].includes(k)?1:ui.shopQty)+' leaves','purchase', 'primary',state.gold<d.price*(['sword','robe'].includes(k)?1:ui.shopQty)||['sword','robe'].includes(k)&&state.items[k]>0)}<small class="detail-help">${['sword','robe'].includes(k)&&state.items[k]?'Your party already owns this equipment.':'Purchased supplies are shared by both travelers.'}</small>`;}
 else if(k&&ui.target){detail+=`<div class="ui-section-heading"><h4>Choose a traveler</h4><button class="text-button" data-ui="target-back">Back</button></div>${heroes.map((h,i)=>`<button class="target-card" data-use="${i}" ${itemDisabled(k,i)?'disabled':''}>${face(i)}<div><h4>${h.name}</h4>${statBar(h)}${statBar(h,'sp')}<small>${itemDisabled(k,i)||'Use '+d.name}</small></div></button>`).join('')}`;}
 else if(k){detail+=m.category==='equipment'?button('Manage equipment','equip-view'):m.category==='key'?'<div class="ui-note">A story item. Follow the journal to find its purpose.</div>':button('Use item '+icon('arrow'),'target');}
 return {content,detail};
}
function equipmentPage(){const i=ui.hero,h=heroes[i],atk=h.atk+(i===0&&state.equipped.sword?14:0),def=h.def+(i===1&&state.equipped.robe?7:0),owned=i===0?state.items.sword:state.items.robe,k=i===0?'sword':'robe';const content=`<div class="hero-switch">${heroes.map((hero,j)=>`<button data-ui="select-hero:${j}" class="${i===j?'active':''}">${face(j)}<span><b>${hero.name}</b><small>${hero.job}</small></span><em>Lv. ${hero.level}</em></button>`).join('')}</div><div class="traveler-heading"><div class="traveler-sprite" style="background-image:var(--portrait${i})"></div><div><span class="ui-kicker">${h.job}</span><h3>${h.name}</h3><p>Level ${h.level} · ${h.xp} / ${h.level*80} experience</p>${statBar(h)}${statBar(h,'sp')}</div></div><div class="ui-section-heading"><h3>Equipment</h3><span>Changes apply immediately</span></div><div class="equipment-slots"><div>${icon('sword')}<span>Weapon<strong>${i===0&&state.equipped.sword?'Dawnsteel saber':h.weapon}</strong></span></div><div>${icon('shield')}<span>Armor<strong>${i===1&&state.equipped.robe?'Moonwoven cloak':h.armor}</strong></span></div></div><div class="ui-section-heading"><h3>Available upgrade</h3><span>${owned?'Owned':'Available at Sera’s shop'}</span></div><div class="equipment-upgrade">${itemArt(k)}<div><h3>${itemDefs[k].name}</h3><p>${itemDefs[k].desc}</p></div>${button(state.equipped[k]?'Unequip':'Equip','equip:'+k,'primary',!owned)}</div>`;
 const detail=`<span class="ui-kicker">TRAVELER STATS</span><h3>Ready for the road</h3><div class="stat-grid">${[['Attack',atk],['Defense',def],['Max HP',h.maxHp],['Max MP',h.maxSp],['Boost points',h.bp]].map(([n,v])=>`<div><span>${n}</span><b>${v}</b></div>`).join('')}</div><div class="compare-card"><span class="ui-kicker">${state.equipped[k]?'CURRENT BONUS':'UPGRADE PREVIEW'}</span><p>${i===0?'Attack':'Defense'} <strong>${i===0?h.atk:h.def} ${icon('arrow')} ${i===0?h.atk+14:h.def+7}</strong></p><small>${itemMeta[k].effect}</small></div><p class="detail-help">Equipment is unique. Change either traveler here; their supplies and leaves remain shared.</p>`;return {content,detail};}
function abilitiesPage(){let selected=abilityData.find(a=>a.id===ui.selected)||abilityData.find(a=>a.hero===ui.hero);const h=heroes[selected.hero];const content=subtitle('Choose a traveler and inspect their abilities. Elemental weaknesses remove shields; broken enemies take double damage.')+`<div class="hero-switch">${heroes.map((hero,i)=>`<button data-ui="ability-hero:${i}" class="${ui.hero===i?'active':''}">${face(i)}<span><b>${hero.name}</b><small>${hero.sp}/${hero.maxSp} MP</small></span></button>`).join('')}</div><div class="ability-list">${abilityData.filter(a=>a.hero===ui.hero).map(a=>`<button class="ability-card ${a.id===selected.id?'selected':''}" data-ability="${a.id}">${icon(a.icon)}<div><h3>${a.name}</h3><p>${a.target}</p></div><b>${a.cost}<small>MP</small></b></button>`).join('')}</div><div class="ui-note">${icon('spark')} Gain a boost point each round. Spend up to three to strengthen one action.</div>`;
 let detail=`<span class="ui-kicker">${h.name} · ${selected.target}</span><div class="skill-art">${icon(selected.icon)}</div><h3>${selected.name}</h3><span class="effect-tag">${selected.cost} MP</span><p>${selected.text}</p>`;
 if(selected.id==='heal')detail+=`${button('Mend the party','field-heal','primary',heroes[1].hp<=0||heroes[1].sp<9||!heroes.some(h=>h.hp>0&&h.hp<h.maxHp))}<small class="detail-help">Heals the most injured standing traveler. Revive fallen allies with an olive of life.</small>`;else detail+='<div class="ui-note">Available in battle from the Skills command.</div>';return {content,detail};}
function journalPage(){const steps=chapterSteps(),stage=state.quest===0?0:state.quest===1?1:state.quest===2?2:state.quest===3?3:4;return `<div class="journal-lead"><span class="ui-kicker">CHAPTER I · THE RIVERLANDS</span><h3>A light remains</h3><p>The river has gone quiet. Aren and Mira reach Willowmere with a map, a few leaves, and a promise to keep walking.</p></div><div class="quest-current"><span class="ui-kicker">${state.quest===4?'CHAPTER COMPLETE':'CURRENT OBJECTIVE'}</span><h3>${$('#quest-title').textContent}</h3><p>${$('#quest-text').textContent}</p>${button('Show on the map '+icon('arrow'),'section:map','secondary')}</div><ol class="quest-timeline">${steps.map(([n,d],i)=>`<li class="${i<stage?'done':i===stage?'current':''}"><span>${i<stage?'✓':i+1}</span><div><h3>${n}</h3><p>${d}</p></div></li>`).join('')}</ol><div class="discovery-stats"><div><strong>${state.opened.length}/5</strong><span>Treasures opened</span></div><div><strong>${state.defeated.length}/3</strong><span>Encounters cleared</span></div><div><strong>${(state.sceneVisited||['village']).length}/5</strong><span>Places discovered</span></div></div>`}

function localMapSVG(large=false){const X=x=>66+x*1.65,Z=z=>68+z*1.65,w=currentDef.water;return `<rect width="132" height="132" fill="#465f4f"/><path d="M0 18Q30 10 57 22T132 15M0 116Q45 99 89 114T132 109" fill="none" stroke="#92a578" stroke-opacity=".2" stroke-width="12"/><rect x="${X(w.x-w.width/2)}" width="${w.width*1.65}" height="132" fill="#4b8990"/>`+sceneRoads.map(r=>`<polyline points="${r.points.map(p=>X(p.x)+','+Z(p.z)).join(' ')}" stroke="#c4c2a2" stroke-opacity=".85" stroke-width="${r.width*1.65}" fill="none" stroke-linejoin="round"/>`).join('')+buildingPlots.map(p=>`<rect x="${X(p.x-p.w/2)}" y="${Z(p.z-p.d/2)}" width="${p.w*1.65}" height="${p.d*1.65}" fill="#a6aa87" stroke="#2c4946" stroke-width=".8"/>`).join('')+currentDef.exits.map(e=>`<rect x="${X(e.x)-5}" y="${Z(e.z)-5}" width="10" height="10" rx="2" fill="#dfcd87" fill-opacity=".4" stroke="#ffedac" stroke-width="1.2"/><path d="m${X(e.x)-2},${Z(e.z)-2} 4,2 -4,2" fill="none" stroke="#fff3c1" stroke-width="1.5"/>${large?`<text x="${X(e.x)+(e.x>15?-7:7)}" y="${Z(e.z)-8}" text-anchor="${e.x>15?'end':'start'}" font-size="4.2" fill="#fff0b5" font-family="Arial">${e.label}</text>`:''}`).join('')+(large?`<circle cx="${X(player.x)}" cy="${Z(player.z)}" r="2.2" fill="#fff2c9" stroke="#fff"/>`:'');}
updateMinimap=function(){$('#mini-land').innerHTML=localMapSVG();$('#mini-player').setAttribute('fill','#fff1b9');};
function mapPage(){const local=ui.mapMode==='local';return `<div class="map-heading"><span class="ui-kicker">THE RIVERLANDS</span><h3>${local?currentDef.name:'An atlas of the Riverlands'}</h3><p>${local?'The gold thresholds span the road. Walk through a marked area to enter the next scene.':'Select a landmark to inspect it. Discovered places can be revisited from the atlas.'}</p></div><div class="ui-filters map-mode-tabs"><button data-ui="map-mode:world" class="${local?'':'active'}">${icon('map')} Region atlas</button><button data-ui="map-mode:local" class="${local?'active':''}">${icon('arrow')} Local paths & exits</button></div>${local?`<div class="map-layout"><div class="local-map-card"><div class="ui-section-heading"><h3>${currentDef.name}</h3><span>LOCAL AREA</span></div><svg class="large-local-map" viewBox="0 0 132 132" role="img" aria-label="Local map with signed exit areas">${localMapSVG(true)}</svg><div class="map-legend"><span><i class="player-dot"></i> Your party</span><span><i class="exit-dot"></i> Zone threshold</span></div></div><div class="exit-list"><span class="ui-kicker">CONNECTED ROADS</span>${currentDef.exits.map((e,i)=>`<button class="exit-route" data-ui="exit:${i}">${icon('arrow')}<span><b>${e.label}</b><small>${e.facing} road · walk to threshold</small></span>${icon('map')}</button>`).join('')}<div class="ui-note">The marked threshold spans the whole road. There is no need to aim for a single point.</div></div></div>`:regionAtlas()}`;}
function getSlot(n){try{return JSON.parse(localStorage.getItem(n==='auto'?'ember-tide-save-v1':'ember-tide-slot-'+n))}catch(e){return null}}
function saveSlot(n){const data={version:1,state:{...state,mode:'explore'},heroes,position:{x:player.x,z:player.z},savedAt:Date.now()};try{localStorage.setItem('ember-tide-slot-'+n,JSON.stringify(data));notify('Journey saved to slot '+n);sfx('treasure')}catch(e){notify('The browser could not save this journey.')}renderMenu()}
function loadSlot(n){const data=getSlot(n);if(!data)return;localStorage.setItem('ember-tide-save-v1',JSON.stringify(data));titleModal=false;ui.target=null;loadGame();}
function settingRow(title,copy,control){return `<div class="ui-setting"><div><h3>${title}</h3><p>${copy}</p></div>${control}</div>`}
function settingsPage(){const tabs=[['display','Display'],['audio','Audio'],['saves','Save & load'],['controls','Controls']];let body='';
 if(ui.settings==='display')body=settingRow('Field of view','A wider view reveals more of the scene. The camera angle stays fixed.',`<div class="range-setting"><output id="fov-output">${camera.fov}°</output><input id="fov-setting" aria-label="Field of view" type="range" min="30" max="46" value="${camera.fov}"></div>`)+settingRow('World clock','A natural 24-minute cycle. Dawn, sunset, twilight and moonlight continue across your journey.',`<span class="clock-setting">${worldTimeLabel()} · ${solar.phase}</span>`)+settingRow('Render quality','Adjust the drawing resolution for this device.',button(state.quality==='low'?'Balanced':'High','quality','secondary'))+settingRow('Fullscreen','Give the Riverlands a little more room.',button(document.fullscreenElement?'Exit fullscreen':'Enter fullscreen','fullscreen','secondary'))+settingRow('Camera shake','A brief impact response during battle.',button(state.reduceMotion?'Reduced':'Standard','motion','secondary'));
 if(ui.settings==='audio')body=settingRow('Music & sound','Ambient melody and battle sound effects.',button(state.sound?'Enabled':'Muted','sound','secondary'))+'<div class="ui-note">Audio starts after your first interaction. Your choice applies throughout the journey.</div>';
 if(ui.settings==='saves')body=subtitle('Three manual slots, plus the most recent automatic save. Saves stay in this browser.')+`<div class="save-slots">${['auto',1,2,3].map(n=>{const d=getSlot(n),area=d?.state?.area,when=d?.savedAt?new Date(d.savedAt).toLocaleString():'';return `<article class="save-slot"><div class="slot-number">${n==='auto'?icon('clock'):'0'+n}</div><div><span class="ui-kicker">${n==='auto'?'AUTOMATIC SAVE':'MANUAL SLOT '+n}</span><h3>${d?(sceneDefs[area]?.name||'The Riverlands'):'An unwritten journey'}</h3><p>${d?`Aren Lv. ${d.heroes?.[0]?.level||1} · ${d.state.gold} leaves · ${Math.floor(d.state.playtime/60)} min`:'Save your current adventure here.'}</p>${when?`<small>${when}</small>`:''}</div><div class="slot-actions">${n!=='auto'?button('Save','save-slot:'+n,'secondary',titleModal):''}${button('Load','load-slot:'+n,'primary',!d)}</div></article>`}).join('')}</div>`;
 if(ui.settings==='controls')body=controlsPage();
 return `<div class="ui-filters settings-tabs">${tabs.map(([id,n])=>`<button data-ui="settings:${id}" class="${ui.settings===id?'active':''}">${n}</button>`).join('')}</div>${body}<div class="settings-bottom">${button(titleModal?'Back to title':'Return to title','title','quiet')}${subtitle('Progress saves automatically after travel, treasure, rest and victories.')}</div>`;
}
function controlsPage(){return `<div class="control-sections">${[['Explore','WASD or arrow keys','Move your party through the world.','Click the ground','Find a walkable route to that spot.','Shift','Run while using movement keys.','E or Enter','Talk, collect treasure, use waystones.'],['Find your way','M','Open the region and local maps.','T','Open village services.','I or Tab','Open the satchel.','Esc','Back out of a submenu or pause.'],['Menus & battle','↑ / ↓','Move between available commands.','← / →','Switch journal sections or enemy target.','Enter / Space','Confirm the selected command.','B','Boost the next battle action.'],['View & rest','Mouse wheel','Zoom the fixed-angle camera.','F','Toggle fullscreen.','H','Hide or show the exploration HUD.','Settings','Change FOV, sound and save slots.']].map(([title,...rows])=>`<section class="control-card"><h3>${title}</h3>${Array.from({length:rows.length/2},(_,i)=>`<div><kbd>${rows[i*2]}</kbd><p>${rows[i*2+1]}</p></div>`).join('')}</section>`).join('')}</div><div class="ui-note">${icon('shield')} In battle, hit a weakness to remove shields. Break the last shield to interrupt a foe and deal double damage. Defend reduces incoming damage until the next round.</div>`}

renderMenu=function(){ui.result=null;let title='Your journey',content='',detail='';
 if(modalTab==='overview')content=overviewPage();
 else if(modalTab==='items'||modalTab==='shop'){title=modalTab==='shop'?'Sera’s provisions':'The satchel';({content,detail}=inventoryPage(modalTab==='shop'));}
 else if(modalTab==='equipment'){title='Your travelers';({content,detail}=equipmentPage());}
 else if(modalTab==='abilities'){title='The light within';({content,detail}=abilitiesPage());}
 else if(modalTab==='journal'){title='A traveler’s journal';content=journalPage();}
 else if(modalTab==='map'){title='The Riverlands';content=mapPage();}
 else if(modalTab==='settings'){title='A moment of quiet';content=settingsPage();}
 else if(modalTab==='controls'){title='A traveler’s guide';content=controlsPage();}
 else{modalTab='overview';content=overviewPage()}
 renderShell(title,modalTab==='shop'?'WILLOWMERE · MERCHANT':'EMBER & TIDE / '+(titleModal?'MAIN MENU':currentDef.name.toUpperCase()),content,detail);
};
function bindUIActions(){
 $$('[data-map-select]').forEach(b=>b.onclick=()=>{ui.mapSelected=b.dataset.mapSelect;renderMenu()});
 $$('[data-ui]').forEach(b=>b.onclick=()=>uiAction(b.dataset.ui));$$('[data-select]').forEach(b=>b.onclick=()=>{ui.selected=b.dataset.select;ui.target=null;renderMenu()});$$('[data-filter]').forEach(b=>b.onclick=()=>{ui.category=b.dataset.filter;ui.target=null;renderMenu()});$$('[data-ability]').forEach(b=>b.onclick=()=>{ui.selected=b.dataset.ability;renderMenu()});$$('[data-travel]').forEach(b=>b.onclick=()=>travel(b.dataset.travel));$$('[data-use]').forEach(b=>b.onclick=()=>{const k=ui.selected;if(!itemDisabled(k,+b.dataset.use)&&useItem(k,+b.dataset.use)){ui.target=null;saveGame(false);renderMenu()}});
 if($('#inventory-search'))$('#inventory-search').oninput=e=>{const pos=e.target.selectionStart;ui.query=e.target.value;renderMenu();const input=$('#inventory-search');input.focus();input.setSelectionRange(pos,pos)};
 if($('#fov-setting'))$('#fov-setting').oninput=e=>{camera.fov=+e.target.value;camera.updateProjectionMatrix();$('#fov-output').textContent=e.target.value+'°'};
}
function uiAction(value){const [action,arg]=value.split(':');sfx('click');
 if(action==='map-mode'){ui.mapMode=arg;renderMenu();return}
 if(action==='atlas-travel'){travel(arg);return}
 if(action==='section'){ui.target=null;modalTab=arg;renderMenu();return}
 if(action==='hero'||action==='select-hero'){ui.hero=+arg;modalTab='equipment';renderMenu();return}
 if(action==='ability-hero'){ui.hero=+arg;ui.selected=abilityData.find(a=>a.hero===ui.hero).id;renderMenu();return}
 if(action==='target'){ui.target=ui.selected;renderMenu();return}if(action==='target-back'){ui.target=null;renderMenu();return}
 if(action==='equip-view'){ui.hero=ui.selected==='sword'?0:1;modalTab='equipment';renderMenu();return}
 if(action==='equip'){state.equipped[arg]=!state.equipped[arg];renderParty();saveGame(false);renderMenu();return}
 if(action==='quantity'){ui.shopQty=clamp(ui.shopQty+(+arg),1,20);renderMenu();return}
 if(action==='purchase'){const k=ui.selected,n=['sword','robe'].includes(k)?1:ui.shopQty,total=n*itemDefs[k].price;if(state.gold<total||['sword','robe'].includes(k)&&state.items[k])return;state.gold-=total;state.items[k]+=n;notify(`Purchased ${itemDefs[k].name} × ${n}`);sfx('treasure');renderParty();saveGame(false);renderMenu();return}
 if(action==='field-heal'){const h=heroes[1];if(h.sp<9||h.hp<=0)return;const target=heroes.filter(h=>h.hp>0).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];target.hp=Math.min(target.maxHp,target.hp+100);h.sp-=9;notify('Mending light restores '+target.name);sfx('heal');renderParty();saveGame(false);renderMenu();return}
 if(action==='exit'){const e=currentDef.exits[+arg];closeMenu(true);walkTo(e.x,e.z);return}
 if(action==='settings'){ui.settings=arg;renderMenu();return}
 if(action==='save-slot'){saveSlot(arg);return}if(action==='load-slot'){loadSlot(arg);return}
 if(action==='day'){toggleDay();renderMenu();return}if(action==='sound'){toggleSound();renderMenu();return}
 if(action==='motion'){state.reduceMotion=!state.reduceMotion;renderMenu();return}
 if(action==='quality'){state.quality=state.quality==='low'?'high':'low';renderer.setPixelRatio(Math.min(devicePixelRatio,state.quality==='low'?.85:1.35,1920/innerWidth));resize();renderMenu();return}
 if(action==='fullscreen'){fullscreen();return}if(action==='title'){if(titleModal)closeMenu(true);else returnToTitle();return}
}
closeMenu=function(force=false){if(ui.target&&force!==true){ui.target=null;renderMenu();return}ui.target=null;ui.result=null;polish.baseClose();};
selectItem=function(k){ui.selected=k;ui.target=['herb','ether','revive'].includes(k)?k:null;modalTab=['sword','robe'].includes(k)?'equipment':'items';if(modalTab==='equipment')ui.hero=k==='sword'?0:1;renderMenu()};

renderParty=function(){$('#coins').innerHTML=icon('coin')+'<b>'+state.gold.toLocaleString()+'</b>';$('#party').innerHTML=heroes.map((h,i)=>`<div class="hud-traveler ${battle?.turn===i?'active':''}">${face(i)}<div class="hud-traveler-body"><div><strong>${h.name}</strong><span>Lv. ${h.level}</span></div>${statBar(h)}${statBar(h,'sp')}</div></div>`).join('');updateQuest()};
ensureJourneyUI=function(){polish.baseEnsure();if(document.body.classList.contains('polished'))return;document.body.classList.add('polished');$('#intro-content').innerHTML=`<div class="title-mark">${icon('spark')}<span>THE RIVERLANDS · CHAPTER I</span></div><h1>EMBER<span>&</span>TIDE</h1><div class="title-rule"></div><p class="title-copy">A quiet river. A fading ward.<br>Two travelers, and a little light to carry.</p><div class="main-menu-actions"><button class="title-button" id="start-btn" disabled><span><small>01</small>New journey</span>${icon('arrow')}</button><button class="title-button hidden" id="continue-btn"><span><small>02</small>Continue</span>${icon('arrow')}</button><button class="title-button" id="title-settings"><span><small>03</small>Settings</span>${icon('gear')}</button><button class="title-button" id="title-controls"><span><small>04</small>How to play</span>${icon('book')}</button></div><div class="title-footer">AN ORIGINAL HD–2D ADVENTURE<br><span>Mouse, keyboard or touch. Your road, your pace.</span></div>`;
 $('#title-settings').onclick=()=>openTitleMenu('settings');$('#title-controls').onclick=()=>openTitleMenu('controls');$('#map-btn').innerHTML=icon('map')+'<span>Map</span><kbd>M</kbd>';$('#town-btn').innerHTML=icon('home')+'<span>Village</span><kbd>T</kbd>';$('#menu-btn').innerHTML=icon('bag')+'<span>Journal</span><kbd>Esc</kbd>';$('#time-btn').innerHTML=icon('spark');$('#audio-btn').innerHTML=icon('spark');$('.objective').insertAdjacentHTML('afterbegin',`<div class="quest-symbol">${icon('book')}</div>`);$('.bottomstrip .keys').innerHTML='<span><kbd>WASD</kbd> / <kbd>↑↓←→</kbd> Move</span><span><kbd>E</kbd> Interact</span><span>Click ground to walk</span>';
};
const polishInput=setupInput;
setupInput=function(){polishInput();$('#menu-btn').onclick=()=>openMenu('overview');document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.mode==='explore'){e.preventDefault();e.stopImmediatePropagation();openMenu('overview')}},true);};
const oldTown=toggleTownMenu;
const villageGardens=settlement;
settlement=function(){villageGardens();for(const [x,z,color] of [[4,9.5,'#edbfd3'],[18,9,'#c6c1ec'],[-24,7,'#f3dfae']]){const stone=stoneMaterial('#b9bfa6'),soil=mat('#536346',{map:assets.grass});for(const side of [-1,1]){box(2.7,.3,.15,stone,x,.15,z+side*.65);box(.15,.3,1.2,stone,x+side*1.28,.15,z)}box(2.4,.12,1.1,soil,x,.1,z);addObstacle(x,z,2.7,1.4);const flowers=new THREE.InstancedMesh(petalGeometry(),mat(color,{map:assets.petal,vertexColors:true,side:THREE.DoubleSide}),72);flowers.receiveShadow=true;flowers.frustumCulled=false;for(let i=0;i<72;i++){const o=new THREE.Object3D();o.position.set(x+rr(-1.1,1.1),.18,z+rr(-.48,.48));o.rotation.y=rr(0,6.28);o.scale.setScalar(rr(.45,.77));o.updateMatrix();flowers.setMatrixAt(i,o.matrix);}world.add(flowers);applyWind(flowers,'grass');flowerMeshes.push(flowers);}};
const completeWoodland=woodlandScene;
woodlandScene=function(){completeWoodland();chest('woodland',7,-1);};
toggleTownMenu=function(){if(state.mode!=='explore')return;if(state.area!=='village'){openMenu('map');return}const el=$('#town-actions');if(!el.classList.contains('hidden')){el.classList.add('hidden');return}oldTown();el.innerHTML=`<div class="service-heading"><span class="ui-kicker">WILLOWMERE</span><h3>Village life</h3><p>A little rest before the road.</p></div><div class="service-list">${[['talk','party','Talk','Meet the townsfolk'],['shop','shop','Provisions','Supplies & equipment'],['inn','home','The Willow & Wren','Rest · 20 leaves'],['save','save','Save journey','Keep your progress'],['leave','map','Riverbank Walk','Follow the eastern road']].map(([id,i,n,sub])=>`<button data-town="${id}">${icon(i)}<span><b>${n}</b><small>${sub}</small></span>${icon('arrow')}</button>`).join('')}</div><button class="service-close" data-service-close>Close <kbd>Esc</kbd></button>`;el.querySelector('[data-service-close]').onclick=()=>el.classList.add('hidden');$$('[data-town]').forEach(b=>b.onclick=()=>{const id=b.dataset.town;if(id==='save'){saveGame();return}if(id==='shop'){goToObject(objects.find(o=>o.type==='merchant'),()=>{ui.category='all';ui.selected='herb';openMenu('shop')});return}if(id==='inn'){goToObject(objects.find(o=>o.type==='inn'));return}if(id==='leave'){walkTo(currentDef.exits[0].x,currentDef.exits[0].z);el.classList.add('hidden');return}goToObject(objects.filter(o=>o.type==='npc').sort((a,b)=>Math.hypot(a.x-player.x,a.z-player.z)-Math.hypot(b.x-player.x,b.z-player.z))[0])});};
showDialog=function(speaker,text,choices){state.mode='dialog';keys={};playerRoute=[];targetPoint=null;dialogue={speaker,text,choices};const cs=choices||[{text:'Continue',fn:closeDialog}];dialogue.next=cs[0].fn;const person=objects.find(o=>o.person&&speaker.toLowerCase().includes(o.person.split(' ')[0].toLowerCase())),index=person?.actor?.index,im=index!==undefined?assets.frames[index]?.[0]?.image:null;const portrait=im?`<div class="dialog-sprite" style="background-image:url('${im.toDataURL()}')"></div>`:`<div class="dialog-symbol">${icon('spark')}</div>`;$('#dialog').innerHTML=`${portrait}<div class="dialog-body"><div class="dialog-speaker">${speaker}</div><p>${text}</p><div class="dialog-actions">${cs.map((c,i)=>`<button class="ui-button ${i===0?'primary':'secondary'}" data-choice="${i}">${c.text}${i===0?icon('arrow'):''}</button>`).join('')}</div></div>`;$('#dialog').classList.remove('hidden');$$('[data-choice]').forEach(b=>b.onclick=()=>cs[+b.dataset.choice].fn());$('#interaction').style.display='none'};

function battleRows(){if(battlePage==='skills')return abilityData.filter(a=>a.hero===battle.turn).map(a=>({...a,label:a.name,note:a.target}));return [{id:'attack',label:'Attack',icon:'sword',note:'Weapon strike · one foe',cost:0},{id:'skills',label:'Skills',icon:'spark',note:'Use a special ability',cost:0},{id:'items',label:'Items',icon:'bag',note:'Open the party satchel',cost:0},{id:'defend',label:'Defend',icon:'shield',note:'Reduce incoming damage',cost:0},{id:'flee',label:'Retreat',icon:'arrow',note:'Leave the encounter safely',cost:0}]}
renderBattle=function(){if(!battle)return;const h=heroes[battle.turn],turnKey=battle.round*10+battle.turn;if(lastBattleTurn!==turnKey){battlePage='commands';commandIndex=0;lastBattleTurn=turnKey}const busy=battle.busy||battle.phase!=='party';$('#battle-message').textContent=battle.log;$('#turn-order').innerHTML=heroes.map((h,i)=>`<span class="turn-token ${battle.turn===i&&battle.phase==='party'?'current':''}">${h.name}${h.hp<=0?' · DOWN':''}</span>`).join('')+battle.enemies.filter(e=>e.hp>0).map(e=>`<span class="turn-token ${e.broken?'broken':''}">${e.broken?'BREAK':e.name}</span>`).join('');
 const rows=battleRows();$('#battle-controls').innerHTML=`<div class="battle-command-head"><div><span class="ui-kicker">ROUND ${battle.round}</span><strong>${battle.phase==='enemy'?'Enemy turn':h.name+'’s turn'}</strong></div><span class="turn-counter">${battle.turn+1}<small>/ 2</small></span></div><div class="battle-command-list">${rows.map((a,i)=>`<button data-combat="${a.id}" class="${commandIndex===i?'selected':''}" ${busy||h.sp<a.cost?'disabled':''}>${icon(a.icon)}<span><strong>${a.label}</strong><small>${a.note}</small></span>${a.cost?`<b>${a.cost}<small>MP</small></b>`:icon('arrow')}</button>`).join('')}${battlePage==='skills'?`<button id="skills-back">${icon('back')}<span>Back to commands</span></button>`:''}</div><button id="boost-btn" class="battle-boost" ${busy||h.bp<=battle.boost||battle.boost>=3?'disabled':''}><span><kbd>B</kbd> Boost ${battle.boost?'+'+battle.boost:''}</span><b>${'●'.repeat(Math.max(0,h.bp-battle.boost))}${'○'.repeat(Math.max(0,5-h.bp+battle.boost))}</b></button>`;
 $$('[data-combat]').forEach((b,i)=>{b.onpointerenter=()=>{commandIndex=i;$$('[data-combat]').forEach(el=>el.classList.toggle('selected',el===b))};b.onclick=()=>{const id=b.dataset.combat;if(id==='skills'){battlePage='skills';commandIndex=0;renderBattle()}else if(id==='flee')flee();else combatAction(id)}});$('#boost-btn').onclick=boost;if($('#skills-back'))$('#skills-back').onclick=()=>{battlePage='commands';renderBattle()};
 if(battle.target<0||!battle.enemies[battle.target]||battle.enemies[battle.target].hp<=0)battle.target=battle.enemies.findIndex(e=>e.hp>0);const e=battle.enemies[battle.target];$('#enemy-readout').innerHTML=e?`<div class="enemy-target-heading"><span class="ui-kicker">TARGET ${battle.target+1} / ${battle.enemies.length}</span><button id="next-target" aria-label="Next enemy">${icon('arrow')}</button></div><h3>${e.name}</h3><div class="enemy-health"><i style="width:${e.hp/e.maxHp*100}%"></i></div><div class="enemy-vitals"><strong>${e.hp}<small> / ${e.maxHp} HP</small></strong><span class="shield-count ${e.broken?'is-broken':''}">${icon('shield')}${e.broken?'BREAK':e.shield}</span></div><div class="weaknesses"><span>Weak to</span>${e.weak.map(w=>`<i title="${w}">${icon({sword:'sword',fire:'flame',ice:'ice',lightning:'bolt'}[w])}</i>`).join('')}</div>`:'';if($('#next-target'))$('#next-target').onclick=()=>selectEnemy(1);
 $('#enemy-labels').innerHTML=battle.enemies.map((e,i)=>e.hp>0?`<button class="enemy-target ${battle.target===i?'selected':''}" data-enemy="${i}" aria-label="Target ${e.name}">▼</button>`:'').join('');$$('[data-enemy]').forEach(b=>b.onclick=()=>{battle.target=+b.dataset.enemy;renderBattle()});renderParty();positionBattleLabels();
};
battleItems=function(selected=null){if(!battle||battle.busy)return;const controls=$('#battle-controls');controls.innerHTML=`<div class="battle-command-head"><div><span class="ui-kicker">PARTY SATCHEL</span><strong>${selected?'Choose a traveler':'Use a supply'}</strong></div>${icon('bag')}</div><div class="battle-command-list">${selected?heroes.map((h,i)=>`<button data-btarget="${i}" ${itemDisabled(selected,i)?'disabled':''}>${face(i)}<span><strong>${h.name}</strong><small>${itemDisabled(selected,i)||`HP ${h.hp}/${h.maxHp} · MP ${h.sp}/${h.maxSp}`}</small></span></button>`).join(''):['herb','ether','revive'].map(k=>`<button data-bitem="${k}" ${state.items[k]===0?'disabled':''}>${icon(itemMeta[k].icon)}<span><strong>${itemDefs[k].name}</strong><small>${itemMeta[k].effect}</small></span><b>× ${state.items[k]}</b></button>`).join('')}<button id="battle-back">${icon('back')}<span>Back</span></button></div>`;$('#battle-back').onclick=()=>selected?battleItems():renderBattle();$$('[data-bitem]').forEach(b=>b.onclick=()=>battleItems(b.dataset.bitem));$$('[data-btarget]').forEach(b=>b.onclick=()=>{const i=+b.dataset.btarget;if(useItem(selected,i,true)){spell('heal',heroMeshes[i].mesh.position);battle.log=itemDefs[selected].name+' restores '+heroes[i].name+'.';battle.busy=true;renderBattle();schedule(.8,finishHeroTurn)}});};
function showResult(title,kicker,text,stats,buttonId,buttonText){ui.result=title;state.mode='menu';$('#modal').classList.remove('hidden');$('#modal').innerHTML=`<section class="ui-result" role="dialog" aria-modal="true" aria-label="${title}"><div class="result-emblem">${icon('spark')}</div><span class="ui-kicker">${kicker}</span><h2>${title}</h2><div class="result-rule"></div><p>${text}</p><div class="result-stats">${stats.map(([n,v])=>`<div><b>${v}</b><span>${n}</span></div>`).join('')}</div><button class="ui-button primary" id="${buttonId}">${buttonText}${icon('arrow')}</button></section>`;$('#'+buttonId).onclick=()=>closeMenu(true);}
winBattle=function(){const boss=battle.source.boss;polish.baseWin();showResult('Victory','THE ROAD GROWS QUIET',boss?'The old ward falls still. The living ember waits at the altar.':'The road ahead is clear. Your travelers grow a little stronger.',[['Experience',boss?115:45],['Leaves',boss?180:70],['Healing grape','+1']],'victory-close','Continue the journey')};
showEnding=function(){showResult('A light remains','CHAPTER I · COMPLETE','The river remembers the stars. Two travelers. One small kindness. A village alight again.',[['Chapter','I'],['Reward','300 ◈'],['The ward','Restored']],'ending-close','Keep wandering');sfx('victory')};

const polishedText=window.render_game_to_text;
window.render_game_to_text=()=>JSON.stringify({...JSON.parse(polishedText()),ui:{section:modalTab,target:ui.target,category:ui.category,mapMode:ui.mapMode||'world',manualSaveSlots:3},exits:currentDef.exits.map(e=>({to:e.to,label:e.label,x:e.x,z:e.z,width:6.2,depth:4.7})),sprites:atlasAudit.map(a=>({index:a.index,poses:a.poseCount,canvas:a.canvas})),flowers:flowerMeshes.reduce((n,m)=>n+m.count,0)});

// Journal pages pause the 3D backdrop. The title screen keeps its living scene loop.
const cinematicRender=render;let menuRenderSignature='';
render=function(){const paused=state.mode==='menu'||titleModal,signature=[state.mode,titleModal,world?.id,state.area,camera?.fov,zoom,innerWidth,innerHeight,Math.round(nightBlend*10)].join('/');if(paused&&signature===menuRenderSignature)return;menuRenderSignature=paused?signature:'';cinematicRender();};
